CREATE TABLE public.portal_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reference text NOT NULL DEFAULT ('FOR-'||upper(substr(gen_random_uuid()::text,1,8))), kind text NOT NULL CHECK(kind IN ('contract','service','mission','report','complaint','invoice','payment','notification')), owner_id uuid REFERENCES public.profiles(id), provider_id uuid REFERENCES public.profiles(id), parent_id uuid REFERENCES public.portal_records(id), title text NOT NULL, status text NOT NULL DEFAULT 'nouvelle', start_date date, end_date date, due_date date, amount numeric(14,2) NOT NULL DEFAULT 0 CHECK(amount>=0), attributes jsonb NOT NULL DEFAULT '{}'::jsonb, created_by uuid NOT NULL DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.portal_records TO authenticated;
GRANT ALL ON public.portal_records TO service_role;
ALTER TABLE public.portal_records ENABLE ROW LEVEL SECURITY;
CREATE INDEX portal_records_owner ON public.portal_records(owner_id,kind);
CREATE INDEX portal_records_provider ON public.portal_records(provider_id,kind);
CREATE INDEX portal_records_parent ON public.portal_records(parent_id);
CREATE OR REPLACE FUNCTION public.portal_record_staff(k text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(auth.uid(),'admin') OR public.portal_can(CASE WHEN k IN ('mission','service') THEN 'operations' WHEN k='report' THEN 'reports' WHEN k IN ('invoice','payment') THEN 'finance' WHEN k='contract' THEN 'contracts' WHEN k='complaint' THEN 'complaints' ELSE 'clients' END) $$;
REVOKE ALL ON FUNCTION public.portal_record_staff(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.portal_record_staff(text) TO authenticated;
CREATE POLICY records_read ON public.portal_records FOR SELECT TO authenticated USING(public.portal_record_staff(kind) OR (owner_id=auth.uid() AND kind IN ('contract','service','complaint','invoice','payment','notification') AND status<>'brouillon') OR (owner_id=auth.uid() AND kind='report' AND status='validé') OR (provider_id=auth.uid() AND kind IN ('mission','report','payment','notification') AND status<>'brouillon'));
CREATE POLICY records_insert ON public.portal_records FOR INSERT TO authenticated WITH CHECK(public.portal_record_staff(kind) OR (kind='complaint' AND owner_id=auth.uid() AND provider_id IS NULL AND status='nouvelle' AND amount=0 AND created_by=auth.uid()) OR (kind='report' AND provider_id=auth.uid() AND status='soumis' AND amount=0 AND created_by=auth.uid() AND EXISTS(SELECT 1 FROM public.portal_records m WHERE m.id=parent_id AND m.kind='mission' AND m.provider_id=auth.uid() AND m.status IN ('acceptée','en cours','en attente de validation'))));
CREATE POLICY records_staff_update ON public.portal_records FOR UPDATE TO authenticated USING(public.portal_record_staff(kind)) WITH CHECK(public.portal_record_staff(kind));
CREATE TABLE public.portal_audit (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid, record_id uuid, action text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.portal_audit TO authenticated;
GRANT ALL ON public.portal_audit TO service_role;
ALTER TABLE public.portal_audit ENABLE ROW LEVEL SECURITY;
CREATE POLICY audit_admin_read ON public.portal_audit FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE OR REPLACE FUNCTION public.audit_portal_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.portal_audit(actor_id,record_id,action) VALUES(auth.uid(),coalesce(new.id,old.id),TG_TABLE_NAME||':'||TG_OP); RETURN coalesce(new,old); END $$;
CREATE TRIGGER portal_record_audit AFTER INSERT OR UPDATE ON public.portal_records FOR EACH ROW EXECUTE FUNCTION public.audit_portal_change();
CREATE TRIGGER portal_roles_audit AFTER INSERT OR UPDATE OR DELETE ON public.portal_roles FOR EACH ROW EXECUTE FUNCTION public.audit_portal_change();